#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m;
    while(cin>>n>>m && (n||m)){
        int x,y,k; cin>>x>>y>>k;
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<m;i++){
            int u,v,l; cin>>u>>v>>l;
            adj[u].push_back({v,l});
        }
        vector<int> cnt(n+1,0);
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
        pq.push({0,x});
        long long ans=-1;
        while(!pq.empty()){
            auto top = pq.top(); pq.pop();
            long long d = top.first; int u = top.second;
            if(cnt[u]>=k) continue;
            cnt[u]++;
            if(u==y && cnt[u]==k){ ans=d; break; }
            for(auto& e : adj[u]) pq.push({d+e.second, e.first});
        }
        cout << ans << "\n";
    }
}

