#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m;
    while(cin>>n>>m && (n||m)){
        int x,y,k; cin>>x>>y>>k;
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<m;i++){
            int u,v,l; cin>>u>>v>>l;
            adj[u].push_back({v,l});
        }
        vector<long long> dist(n+1, LLONG_MAX);
        dist[x]=0;
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
        pq.push({0,x});
        while(!pq.empty()){
            auto top = pq.top(); pq.pop();
            long long d = top.first; int u = top.second;
            if(d>dist[u]) continue;
            for(auto& e : adj[u]) if(dist[u]+e.second < dist[e.first]){ dist[e.first]=dist[u]+e.second; pq.push({dist[e.first], e.first}); }
        }
        cout << (dist[y]==LLONG_MAX? -1 : dist[y]) << "\n";
    }
}
